/* Binary-searches a sorted array of fixed-size records using a compare callback; returns the matching record or 0. */
s32 binarySearchRecords(s32 key, s32 base, s32 count, s32 recordSize, s32 (*compare)(s32, s32)) { s32 record, midIndex, mid, order, high, low, unusedSum; if (count != 0) { low=1; high=count; do { mid=(low+high)>>1; midIndex=mid-1; record=base+recordSize*midIndex; order=compare(key,record); if (order==0) return record; if (order<0) high=midIndex; else low=mid+1; unusedSum=low+high; } while (high>=low); } return 0; }
